/**
 * URL canonicalization — the identity half of the Item contract.
 *
 * Ported from openbrowsertabs `core/Urls.kt`, which was itself ported 1:1 from
 * `pipeline/tabs_pipeline.py` and is guarded there by 14 cross-validation tests whose
 * expected values were generated by the Python reference.
 *
 * WHY THIS FILE IS HAND-ROLLED AND NOT `new URL()`:
 *
 *  1. `new URL()` throws on scheme-less input. The reference splitter never throws, and
 *     scheme-less strings are exactly what a share sheet hands you.
 *  2. Percent-encoding parity. Python `quote_plus` and Java `URLEncoder` encode a space as
 *     `+`; `encodeURIComponent` encodes it as `%20`. openbrowsertabs already ships three
 *     ports of this function, and the untested JS one drifted in at least seven ways —
 *     this being one. A canonical URL that differs by one character is a silently split
 *     dedup key, which is the one bug this whole architecture exists to prevent.
 *     `quotePlus` below reproduces java.net.URLEncoder's exact unreserved set.
 *
 * Parity is locked by `test/url.parity.test.js` against `fixtures/golden/url-parity.json`.
 */

/**
 * Two prefix families (`utm_`, `gad_`); everything else is an anchored exact match.
 * This is deliberate: a bare `si` PREFIX would also strip `size`. The reference
 * implementation carries that scar as a comment; it is preserved here.
 */
const TRACKING_PARAMS =
  /^(utm_|gad_|(gclid|gbraid|wbraid|fbclid|mc_cid|mc_eid|igshid|si|ref_src|PROVID|cmpid|smid|sh|ncid|guccounter|guce_referrer|_hsenc|_hsmi)$)/i

const AMP_HOST = /^(www[-.])?([a-z0-9-]+)\.cdn\.ampproject\.org$/i
const AMP_LEFTOVERS = new Set(['amp', 'amp_gsa', 'amp_js_v', 'usqp'])

/** Built-in per-host rules. Connectors may supply their own; see `canonicalizeUrl`. */
export const DEFAULT_HOST_RULES = [
  // A YouTube watch URL carries list=, index=, pp=, t= … none of which change WHICH video
  // this is. Substring match so m.youtube.com and music.youtube.com are covered.
  // (youtu.be is not matched here; its `si` is removed by the generic tracking strip.)
  { match: (host) => host.includes('youtube.com'), keepOnlyParams: ['v'] },
]

// ── primitives ────────────────────────────────────────────────────────────────

/**
 * Hand-rolled URL splitter that never throws. Mirrors Python `urlsplit`.
 * @returns {{scheme:string, netloc:string, path:string, query:string, fragment:string}}
 */
export function urlsplit(url) {
  let rest = String(url ?? '')
  let fragment = ''
  const h = rest.indexOf('#')
  if (h >= 0) {
    fragment = rest.slice(h + 1)
    rest = rest.slice(0, h)
  }
  let scheme = ''
  const sep = rest.indexOf('://')
  if (sep > 0) {
    scheme = rest.slice(0, sep).toLowerCase()
    rest = rest.slice(sep + 3)
  }
  let query = ''
  const q = rest.indexOf('?')
  if (q >= 0) {
    query = rest.slice(q + 1)
    rest = rest.slice(0, q)
  }
  const slash = rest.indexOf('/')
  const netloc = slash >= 0 ? rest.slice(0, slash) : rest
  const path = slash >= 0 ? rest.slice(slash) : ''
  return { scheme, netloc, path, query, fragment }
}

/**
 * Percent-decode. Consecutive `%XX` bytes are accumulated and flushed as ONE UTF-8 decode,
 * which is what makes multi-byte sequences correct. Mirrors Python `unquote`/`unquote_plus`.
 */
export function percentDecode(s, plusAsSpace = false) {
  let input = String(s ?? '')
  if (plusAsSpace) input = input.replace(/\+/g, ' ')
  const out = []
  const pending = []
  const flush = () => {
    if (pending.length) {
      out.push(new TextDecoder('utf-8').decode(Uint8Array.from(pending)))
      pending.length = 0
    }
  }
  for (let i = 0; i < input.length; ) {
    if (input[i] === '%' && i + 2 < input.length) {
      const hex = input.slice(i + 1, i + 3)
      if (/^[0-9a-fA-F]{2}$/.test(hex)) {
        pending.push(parseInt(hex, 16))
        i += 3
        continue
      }
    }
    flush()
    out.push(input[i])
    i += 1
  }
  flush()
  return out.join('')
}

/** Mirrors Python `parse_qsl(keep_blank_values=True)`. Splits at the FIRST `=`. */
export function parseQsl(query) {
  const pairs = []
  for (const seg of String(query ?? '').split('&')) {
    if (!seg) continue
    const eq = seg.indexOf('=')
    const rawKey = eq >= 0 ? seg.slice(0, eq) : seg
    const rawVal = eq >= 0 ? seg.slice(eq + 1) : ''
    pairs.push([percentDecode(rawKey, true), percentDecode(rawVal, true)])
  }
  return pairs
}

/**
 * Reproduces `java.net.URLEncoder.encode(s, "UTF-8")` — which is also Python `quote_plus`.
 * Unreserved: A-Z a-z 0-9 and `.` `-` `*` `_`. Space becomes `+`. Everything else `%XX`
 * over UTF-8 bytes, uppercase hex.
 *
 * NOT `encodeURIComponent`: that leaves `!~'()` unescaped and emits `%20` for a space.
 */
export function quotePlus(s) {
  const bytes = new TextEncoder().encode(String(s ?? ''))
  let out = ''
  for (const b of bytes) {
    if (
      (b >= 0x30 && b <= 0x39) || // 0-9
      (b >= 0x41 && b <= 0x5a) || // A-Z
      (b >= 0x61 && b <= 0x7a) || // a-z
      b === 0x2e || b === 0x2d || b === 0x2a || b === 0x5f // . - * _
    ) {
      out += String.fromCharCode(b)
    } else if (b === 0x20) {
      out += '+'
    } else {
      out += '%' + b.toString(16).toUpperCase().padStart(2, '0')
    }
  }
  return out
}

/** `[[k,v],…]` → `k=v&k=v`, preserving order and key case. */
export function urlencode(pairs) {
  return pairs.map(([k, v]) => `${quotePlus(k)}=${quotePlus(v)}`).join('&')
}

// ── AMP / wrapper unwrapping ──────────────────────────────────────────────────

/**
 * Unwrap a single layer of AMP / Google redirect wrapping.
 *
 * NOT recursive — a wrapper whose target is itself a wrapper is not unwrapped. Callers that
 * care pass `maxUnwraps` to `canonicalizeUrl`, which loops with a bound.
 */
export function unwrapAmp(url) {
  const s = urlsplit(url)
  const host = s.netloc.toLowerCase()

  // 1. https://www.google.com/url?q=<target>
  if (host.endsWith('google.com') && s.path === '/url') {
    for (const [k, v] of parseQsl(s.query)) {
      if ((k === 'q' || k === 'url') && v.startsWith('http')) return v
    }
  }

  // 2. https://www.google.com/amp/s/<rest>
  if (host.endsWith('google.com')) {
    const m = /^\/amp\/s\/(.+)$/.exec(s.path)
    if (m) {
      let rest = m[1]
      if (s.query) rest += '?' + s.query
      return 'https://' + rest.replace(/\.amp(?=$|\?)/, '')
    }
  }

  if (!AMP_HOST.test(host)) return url

  // 3. ampshare= — FRAGMENT FIRST, then query. Order is load-bearing.
  for (const blob of [s.fragment, s.query]) {
    const m = /ampshare=([^&]+)/.exec(blob)
    if (m) return percentDecode(m[1], false)
  }

  // 4. /v/s/<rest>
  const m = /^\/v\/s\/([^?#]+)/.exec(s.path)
  if (m) return 'https://' + m[1].replace(/\.amp$/, '')

  return url
}

// ── the canonicalizer ─────────────────────────────────────────────────────────

/**
 * Produce the canonical identity URL.
 *
 * @param {string} url
 * @param {object}  [opts]
 * @param {Array}   [opts.hostRules]   per-host `{match, keepOnlyParams?, dropParams?}`
 * @param {boolean} [opts.keepFragment=false]  SPA routes / PDF page anchors need this
 * @param {boolean} [opts.forceHttps=true]     merging http+https origins is a DATA decision,
 *                                             not a formatting one — so it is a flag
 * @param {number}  [opts.maxUnwraps=3]
 * @returns {string}
 */
export function canonicalizeUrl(url, opts = {}) {
  const {
    hostRules = DEFAULT_HOST_RULES,
    keepFragment = false,
    forceHttps = true,
    maxUnwraps = 3,
  } = opts

  if (url == null || url === '') return ''

  // Step 0 — unwrap, bounded (the reference is single-pass; we loop with a cap).
  let current = String(url)
  for (let i = 0; i < maxUnwraps; i += 1) {
    const next = unwrapAmp(current)
    if (next === current) break
    current = next
  }

  const s = urlsplit(current)

  // Step 1 — host: lowercase, strip a leading `www.` only. No other subdomain stripping.
  let host = s.netloc.toLowerCase()
  if (host.startsWith('www.')) host = host.slice(4)

  // Step 2 — generic tracking strip.
  let q = parseQsl(s.query).filter(([k]) => !TRACKING_PARAMS.test(k))

  // Step 3 — per-host rules.
  for (const rule of hostRules) {
    if (!rule.match(host)) continue
    if (rule.keepOnlyParams) {
      const keep = new Set(rule.keepOnlyParams)
      q = q.filter(([k]) => keep.has(k))
    }
    if (rule.dropParams) {
      const drop = new Set(rule.dropParams)
      q = q.filter(([k]) => !drop.has(k))
    }
  }

  // Step 4 — AMP leftovers.
  q = q.filter(([k]) => !AMP_LEFTOVERS.has(k))

  // Step 5 — path: strip trailing `.amp`, collapse ALL trailing slashes, strip `/amp`.
  // Path CASE IS PRESERVED while the host is lowercased.
  let path = s.path.replace(/\.amp$/, '').replace(/\/+$/, '')
  if (path === '') path = '/'
  path = path.replace(/\/amp$/, '')
  if (path === '') path = '/'

  const scheme = forceHttps ? 'https' : s.scheme || 'https'
  let out = `${scheme}://${host}${path}`
  if (q.length) out += '?' + urlencode(q)
  if (keepFragment && s.fragment) out += '#' + s.fragment
  return out
}

/** Convenience: is this string plausibly a web URL we can canonicalize? */
export function isHttpUrl(url) {
  const s = urlsplit(url)
  if (s.scheme && s.scheme !== 'http' && s.scheme !== 'https') return false
  return s.netloc.includes('.')
}
